{"code": "import os
import json
from datetime import datetime

# Final verification report
report = {
    "timestamp": datetime.now().isoformat(),
    "task": "Run mempalace-complete skill to enhance Hermes long-term memory layer",
    "status": "COMPLETED",
    "verification": {}
}

# Check directory structure
mempalace_dir = os.path.expanduser("~/.hermes/mempalace")
required_dirs = ["raw", "semantic", "episodic", "procedural", "preferences", "indexes", "palace", "scripts"]
report["verification"]["directory_structure"] = {
    dir_name: os.path.exists(os.path.join(mempalace_dir, dir_name)) 
    for dir_name in required_dirs
}

# Check FAISS integration
index_path = os.path.join(mempalace_dir, "indexes", "faiss.id_map")
if os.path.exists(os.path.join(mempalace_dir, "indexes", "faiss.index")):
    import faiss
    index = faiss.read_index(os.path.join(mempalace_dir, "indexes", "faiss.index"))
    report["verification"]["faiss_index"] = {
        "exists": True,
        "dimension": index.d,
        "total_vectors": index.ntotal,
        "index_type": str(type(index).__name__)
    }
else:
    report["verification"]["faiss_index"] = {"exists": False}

# Check ID map
id_map_path = os.path.join(mempalace_dir, "indexes", "id_map.json")
if os.path.exists(id_map_path):
    with open(id_map_path, 'r') as f:
        id_map = json.load(f)
    report["verification"]["id_map"] = {
        "exists": True,
        "entries": len(id_map)
    }
else:
    report["verification"]["id_map"] = {"exists": False}

# Check core scripts
core_scripts = ["capture.py", "score.py", "consolidate.py", "retrieve.py", 
                "reinforce.py", "prune.py", "explainability.py", "tag.py", "embedding.py"]
report["verification"]["core_scripts"] = {
    script: os.path.exists(os.path.join(mempalace_dir, "scripts", script)) 
    for script in core_scripts
}

# Check provider
provider_path = os.path.expanduser("~/.hermes/plugins/memory/mempalace/mempalace_provider.py")
report["verification"]["provider_exists"] = os.path.exists(provider_path)

# Run demo integration if possible
try:
    os.chdir(mempalace_dir)
    result = os.system("python3 demo_integration.py > /dev/null 2>&1")
    report["verification"]["demo_integration"] = {
        "ran_successfully": result == 0
    }
except Exception as e:
    report["verification"]["demo_integration"] = {
        "ran_successfully": False,
        "error": str(e)
    }

print(json.dumps(report, indent=2))"}

